<script setup>



import {computed} from 'vue'

import HelpTip from '../../shared/components/HelpTip.vue'
import JavaCompileFields from './JavaCompileFields.vue'

import {toast} from '../../shared/composables/toast.js'
import {dockerStep, ensureDockerStep, imageCompiler, setImageCompiler, selectImageDockerfile} from '../imageBuildModel.js'
const props=defineProps({service:{type:Object,required:true}})
const params=computed(()=>dockerStep(props.service)?.params||{})
const compiler=computed(()=>imageCompiler(props.service))
const command=computed({get:()=>props.service.build_cmd||props.service.steps?.find(s=>['java-build','npm-build'].includes(s.step))?.params?.COMMAND||'',set:value=>{props.service.build_cmd=value}})
function changeCompiler(mode){try{setImageCompiler(props.service,mode)}catch(e){toast(e.message,'warning')}}
function changeDockerfile(source,template){try{selectImageDockerfile(props.service,source,template)}catch(e){toast(e.message,'warning')}}
function update(key,value){ensureDockerStep(props.service).params[key]=value}
function output(value){props.service.artifact_glob=value;update('DOCKERFILE_ARTIFACT_PATH',value)}
const preview=computed(()=>params.value.DOCKERFILE_TEMPLATE==='nginx'?`FROM nginx:stable\nCOPY dist/ /usr/share/nginx/html/\nEXPOSE 80`:`FROM eclipse-temurin:21-jre-jammy\nWORKDIR /app\nCOPY app.jar /app/app.jar\nEXPOSE 8888\nENTRYPOINT ["java","-jar","/app/app.jar"]`)
const compilerOptions=computed(()=>{
 const options=[{value:'dockerfile',label:'由 Dockerfile 编译（如多阶段构建）'},{value:'maven',label:'Java · Maven'},{value:'gradle',label:'Java · Gradle'},{value:'java-command',label:'Java · 自定义编译命令'},{value:'node',label:'前端 · Node 编译'}]
 if(params.value.DOCKERFILE_SOURCE!=='template')return options
 return options.filter(o=>params.value.DOCKERFILE_TEMPLATE==='nginx'?o.value==='node':['maven','gradle','java-command'].includes(o.value))
})

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])
const _view2=_viewRef([])
const _view3=_viewRef([])


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Field,FieldDescription,FieldError,FieldLabel,Input,Textarea,Checkbox} from '../../shared/shadcn-ui.js'
</script>

<template><div class="image-build-editor"><h4>源码编译</h4><Field class="fld"><FieldLabel>编译方式</FieldLabel><OptionPicker :model-value="compiler==='dockerfile'&&params.DOCKERFILE_SOURCE==='template'?'':compiler" :options="compilerOptions" :style="{width:'100%',maxWidth:'100%'}" placeholder="运行时基础模板需要前置编译" @update:model-value="changeCompiler"/></Field><template v-if="['maven','gradle'].includes(compiler)"><JavaCompileFields :service="service" :tool="compiler"/><small>请执行 clean，避免把遗留 JAR 打进镜像。</small><Accordion class="platform-collapse" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>编译高级参数</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(&quot;panel&quot;)))"><template v-if="compiler==='maven'"><Field class="fld"><FieldLabel>Maven Profiles</FieldLabel><Input v-model="service.maven_profiles"/></Field><Field class="fld"><FieldLabel>settings.xml（可选）</FieldLabel><Input v-model="service.maven_settings_path"/></Field><Field class="fld"><FieldLabel>-D 属性（每行 key=value）</FieldLabel><Textarea v-model="service.maven_properties" :rows="({minRows:(3),maxRows:Math.max((3),16)}).minRows||4"/></Field></template><template v-else><Field class="fld"><FieldLabel>排除任务</FieldLabel><Input v-model="service.gradle_excluded_tasks"/></Field><Field class="fld"><FieldLabel>-P 项目属性</FieldLabel><Textarea v-model="service.gradle_project_properties" :rows="({minRows:(2),maxRows:Math.max((2),16)}).minRows||4"/></Field><Field class="fld"><FieldLabel>-D 系统属性</FieldLabel><Textarea v-model="service.gradle_system_properties" :rows="({minRows:(2),maxRows:Math.max((2),16)}).minRows||4"/></Field></template></AccordionContent></AccordionItem></Accordion></template><Field v-else-if="compiler!=='dockerfile'" class="fld"><FieldLabel>源码编译命令</FieldLabel><Textarea v-model="command" :placeholder="compiler==='node'?'npm ci && npm run build':'如 ./gradlew clean bootJar'" :rows="({minRows:(2),maxRows:Math.max((2),16)}).minRows||4"/></Field><Field v-if="compiler!=='dockerfile'" class="fld"><FieldLabel>{{compiler==='node'?'静态产物目录':'JAR 产物路径'}}</FieldLabel><Input :model-value="params.DOCKERFILE_SOURCE==='template'?params.DOCKERFILE_ARTIFACT_PATH:service.artifact_glob" :placeholder="compiler==='gradle'?'build/libs/*.jar':compiler==='node'?'dist':'target/*.jar'" @update:model-value="output" v-bind="{&quot;aria-label&quot;:&quot;镜像编译产物路径&quot;}"/><FieldDescription><small>基础模板的路径相对下方构建上下文。必须唯一匹配本次编译产物，多个 JAR 不会自动选最新。</small></FieldDescription></Field><h4>镜像打包</h4><Field class="fld"><FieldLabel>镜像名称</FieldLabel><Input v-model="service.image_name" :placeholder="params.PUSH==='false'?'my-service':'registry.example.com/team/my-service'"/></Field><Field class="fld"><FieldLabel>镜像交付方式</FieldLabel><OptionPicker :model-value="params.PUSH==='false'?'false':'true'" :options="[{value:'true',label:'镜像仓库（推送 / 拉取）'},{value:'false',label:'镜像文件（导出 / 上传，无需仓库）'}]" :style="{width:'100%',maxWidth:'100%'}" @update:model-value="v=>update('PUSH',v)"/></Field><Field class="fld"><FieldLabel>Dockerfile 来源</FieldLabel><OptionPicker :model-value="params.DOCKERFILE_SOURCE||'repository'" :options="[{value:'template',label:'平台运行时模板（前置编译后打包）'},{value:'repository',label:'仓库 Dockerfile（可自行多阶段编译）'},{value:'platform',label:'自定义 Dockerfile'}]" :style="{width:'100%',maxWidth:'100%'}" @update:model-value="v=>changeDockerfile(v)"/></Field><template v-if="params.DOCKERFILE_SOURCE==='template'"><Field class="fld"><FieldLabel>运行时基础模板</FieldLabel><OptionPicker :model-value="params.DOCKERFILE_TEMPLATE||'java21'" :options="[{value:'java21',label:'Java 21 JAR 运行时'},{value:'nginx',label:'Nginx 静态站点运行时'}]" :style="{width:'100%',maxWidth:'100%'}" @update:model-value="v=>changeDockerfile('template',v)"/></Field><Accordion class="platform-collapse" type="multiple" :model-value="(_view2||[]).map(String)" @update:model-value="_view2=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>查看运行时 Dockerfile</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view2||[]).map(String).includes(String(&quot;panel&quot;)))"><pre>{{preview}}</pre><small>只复制经过校验的本次编译产物，不承担源码编译；端口分别为 8888 / 80。</small></AccordionContent></AccordionItem></Accordion></template><Field v-else-if="params.DOCKERFILE_SOURCE==='platform'" class="fld"><FieldLabel>自定义 Dockerfile</FieldLabel><Textarea :model-value="params.DOCKERFILE_CONTENT||''" placeholder="FROM ..." @update:model-value="v=>update('DOCKERFILE_CONTENT',v)" :rows="({minRows:(8),maxRows:Math.max((8),16)}).minRows||4"/><FieldDescription><small>通过标准输入构建，不覆盖仓库文件；上限 32 KiB，不要写入密钥。</small></FieldDescription></Field><Field v-else class="fld"><FieldLabel>仓库 Dockerfile 路径</FieldLabel><Input :model-value="params.DOCKERFILE||'Dockerfile'" @update:model-value="v=>update('DOCKERFILE',v)"/></Field><Accordion class="platform-collapse" type="multiple" :model-value="(_view3||[]).map(String)" @update:model-value="_view3=$event"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>镜像高级参数</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view3||[]).map(String).includes(String(&quot;panel&quot;)))"><Field class="fld"><FieldLabel>构建上下文</FieldLabel><Input :model-value="params.CONTEXT||'.'" @update:model-value="v=>update('CONTEXT',v)"/></Field><Field v-if="params.DOCKERFILE_SOURCE!=='template'" class="fld"><FieldLabel>同时保留本次 JAR（可选）<HelpTip text="填写源码工作区内相对构建上下文的 JAR 路径，例如 target/*.jar。只接受本次生成且唯一匹配的文件；多阶段 Dockerfile 内部的 JAR 需先由项目导出到此路径。同次构建关联不等同于证明镜像使用了该 JAR。"/></FieldLabel><Input :model-value="params.EXPORT_JAR_GLOB||''" placeholder="留空只保留镜像" @update:model-value="v=>update('EXPORT_JAR_GLOB',v)"/></Field><Field class="fld"><FieldLabel>目标平台（可选）</FieldLabel><Input :model-value="params.PLATFORMS||''" placeholder="linux/amd64" @update:model-value="v=>update('PLATFORMS',v)"/></Field></AccordionContent></AccordionItem></Accordion><p class="pipeline-summary">{{compiler==='dockerfile'?(params.DOCKERFILE_SOURCE==='template'?'尚未配置源码编译，不能使用运行时模板':'拉取源码 → Dockerfile 构建'):`拉取源码 → ${compiler==='node'?'Node':'Java'} 编译 → 校验产物 → Docker 打包`}} → {{params.PUSH==='false'?'导出镜像文件':'推送镜像仓库'}}</p></div></template>

<style scoped>.image-build-editor{min-width:0}.image-build-editor h4{font-size:1rem;margin:16px 0 12px}.fld{margin-bottom:12px;min-width:0}.fld>label{display:block;margin-bottom:6px;font-size:.75rem}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.image-build-editor small{display:block;color:var(--muted-foreground);font-size:.75rem;line-height:1.5;margin:6px 0}.image-build-editor pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.75rem}@media(max-width:600px){.two{grid-template-columns:1fr}}</style>
